const microphoneDialog=document.createElement('dialog');microphoneDialog.id='microphoneDialog';microphoneDialog.className='work-dialog';microphoneDialog.style.cssText='width:min(780px,94vw);max-height:92vh;overflow:auto';document.body.append(microphoneDialog);
microphoneDialog.addEventListener('keydown',event=>event.stopPropagation());
let microphoneSession=null;
const micCss=document.createElement('style');micCss.textContent='#microphoneDialog .mic-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}#microphoneDialog select{max-width:280px}#microphoneDialog #micDevice{width:320px;max-width:65%}#microphoneDialog #micTarget{width:210px;max-width:100%}#microphoneDialog button:disabled{opacity:.4;cursor:not-allowed}#microphoneDialog label:has(input[type=checkbox]){justify-content:flex-start;gap:10px}#microphoneDialog .mic-meter{width:100%;height:24px;accent-color:#66d9d0}#microphoneDialog .mic-meter::-webkit-meter-bar{background:#07192f;border:1px solid #355078}#microphoneDialog .mic-meter::-webkit-meter-optimum-value{background:#66d9d0}#microphoneDialog .mic-meter.clipping::-webkit-meter-optimum-value{background:#ff6979}#microphoneDialog .mic-clock{font-size:30px;color:#7fdff0;font-variant-numeric:tabular-nums}#microphoneDialog .mic-buttons{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}#microphoneDialog .mic-live{color:#ffd164}#microphoneDialog .mic-live.recording{color:#ff6979}#microphoneDialog audio{width:100%}#microphoneDialog input[type=range]{width:190px}';document.head.append(micCss);
function microphoneError(error){if(error.name==='NotAllowedError')return 'Permiso de micrófono denegado. Revisa también Configuración de Windows → Privacidad → Micrófono → aplicaciones de escritorio.';if(error.name==='NotFoundError')return 'No se ha encontrado un micrófono conectado.';if(error.name==='NotReadableError')return 'No se puede abrir el micrófono. Puede estar ocupado por otra aplicación.';if(error.name==='OverconstrainedError')return 'La entrada seleccionada ya no está disponible. Actualiza la lista y elige otra.';return error.message||String(error);}
async function openMicrophoneRecorder(){
  if(microphoneSession||exporting||historyBusy||document.querySelector('dialog[open]'))return;
  if(!window.lqtacDesktop?.microphoneRecordingStart){toast('Abre el programa de escritorio actualizado para grabar.');return;}
  stopTimelinePlayback();const s={state:'idle',stream:null,context:null,node:null,gain:null,analyser:null,id:null,queue:Promise.resolve(),backlog:0,frames:0,saved:null,inserted:false,error:null,meter:0,closed:false,previousInert:$('.workspace').inert};microphoneSession=s;$('.workspace').inert=true;
  microphoneDialog.innerHTML='<h2>Grabar audio · micrófono</h2><p>Captura local en WAV PCM de 24 bits, mono, 48 kHz. Sin compresión con pérdida y sin enviar audio a Internet.</p><label>Entrada de audio<select id="micDevice"><option value="default">Micrófono predeterminado</option></select></label><div class="mic-buttons"><button id="micRefresh" type="button">Actualizar entradas</button><button id="micPrepare" type="button">Activar micrófono</button><button id="micDisconnect" type="button" disabled>Desconectar</button></div><label>Ganancia de entrada<input id="micGain" type="range" min="0" max="200" value="100"><output id="micGainValue">100 %</output></label><meter id="micMeter" class="mic-meter" min="0" max="100" value="0" aria-label="Nivel del micrófono"></meter><p id="micLevel">Sin señal · micrófono desconectado</p><p id="micLive" class="mic-live">Micrófono desconectado</p><div id="micClock" class="mic-clock">00:00:00</div><div class="mic-grid"><label>Destino en timeline<select id="micTarget"><option value="new">Nueva pista de audio</option></select></label><label>Posición (s)<input id="micPosition" type="number" min="0" max="604800" step="0.001" value="0"></label></div><label><input id="micAutoInsert" type="checkbox" checked> Insertar en timeline al terminar</label><p>Primero activa la entrada para comprobar el nivel. No se oye por los altavoces mientras capturas. Usa auriculares si hay sonido externo. Al pulsar Grabar elegirás un archivo nuevo; no se sobrescriben tomas existentes.</p><div class="mic-buttons"><button id="micRecord" type="button" disabled>● Grabar WAV…</button><button id="micStop" type="button" disabled>■ Detener y guardar</button><button id="micDiscard" type="button" disabled>Descartar toma</button><button id="micRetry" type="button" disabled>Guardar toma en otra ruta…</button></div><p id="micStatus" role="status">Sin acceso al micrófono hasta pulsar Activar.</p><audio id="micPreview" controls hidden></audio><p id="micSavedPath" style="overflow-wrap:anywhere"></p><footer><button id="micInsert" type="button" disabled>Insertar toma guardada</button><button id="micClose" type="button">Cerrar</button></footer>';
  $('#micPosition').value=timelineTime;
  $$('.track').forEach((track,index)=>{if(track.dataset.kind!=='audio')return;const option=document.createElement('option');option.value=String(index);option.textContent=$$('#trackLabels .track-label strong')[index]?.textContent||track.dataset.track;$('#micTarget').append(option);});
  const status=text=>{if(!s.closed)$('#micStatus').textContent=text;};
  function update(){if(s.closed)return;const busy=['preparing','choosing','recording','stopping','saving','closing'].includes(s.state),locked=busy||s.state==='pending';$('#micDevice').disabled=locked;$('#micRefresh').disabled=locked;$('#micPrepare').disabled=locked||s.state==='ready';$('#micDisconnect').disabled=s.state!=='ready';$('#micGain').disabled=!s.stream;$('#micRecord').disabled=s.state!=='ready';$('#micStop').disabled=s.state!=='recording';$('#micDiscard').disabled=!['recording','pending'].includes(s.state);$('#micRetry').disabled=s.state!=='pending';$('#micInsert').disabled=busy||!s.saved||s.inserted||s.state==='pending';$('#micTarget').disabled=locked;$('#micPosition').disabled=locked;$('#micAutoInsert').disabled=locked;$('#micClose').disabled=['choosing','stopping','saving','closing'].includes(s.state);$('#micLive').textContent=s.state==='recording'?'● GRABANDO · micrófono activo':s.stream?'● Micrófono activo · solo nivel': 'Micrófono desconectado';$('#micLive').classList.toggle('recording',s.state==='recording');$('#micPreview').hidden=!s.saved||!!s.stream;}
  async function devices(){try{const selected=$('#micDevice').value,all=await navigator.mediaDevices.enumerateDevices();if(s.closed)return;const select=$('#micDevice');select.replaceChildren(new Option('Micrófono predeterminado','default'));all.filter(d=>d.kind==='audioinput'&&d.deviceId&&d.deviceId!=='default').forEach((d,i)=>select.append(new Option(d.label||'Entrada '+(i+1),d.deviceId)));if([...select.options].some(o=>o.value===selected))select.value=selected;}catch(e){status(microphoneError(e));}}
  async function release(){cancelAnimationFrame(s.meter);s.meter=0;const stream=s.stream,context=s.context;s.stream=null;s.context=null;if(s.node){s.node.port.onmessage=null;s.node.disconnect();}s.node=null;s.gain?.disconnect();s.gain=null;s.analyser=null;stream?.getTracks().forEach(t=>{t.onended=null;t.stop();});if(context&&context.state!=='closed')await context.close().catch(()=>{});if(!s.closed){$('#micMeter').value=0;$('#micLevel').textContent='Micrófono desconectado';update();}}
  function meter(){if(s.closed||!s.analyser)return;const data=new Float32Array(s.analyser.fftSize);s.analyser.getFloatTimeDomainData(data);let peak=0,squares=0;for(const n of data){peak=Math.max(peak,Math.abs(n));squares+=n*n;}const rms=Math.sqrt(squares/data.length),db=rms>0?20*Math.log10(rms):-Infinity;$('#micMeter').value=Math.max(0,Math.min(100,(db+60)/60*100));$('#micMeter').classList.toggle('clipping',peak>=.98);$('#micLevel').textContent=(Number.isFinite(db)?db.toFixed(1)+' dBFS':'Sin señal')+(peak>=.98?' · ¡Saturación! Reduce la ganancia':'');const seconds=Math.floor(s.frames/(s.rate||48000));$('#micClock').textContent=[Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(v=>String(v).padStart(2,'0')).join(':');s.meter=requestAnimationFrame(meter);}
  async function prepare(){if(!['idle','done'].includes(s.state))return;s.state='preparing';$('#micPreview').pause();update();status('Solicitando acceso al micrófono…');try{const device=$('#micDevice').value,stream=await navigator.mediaDevices.getUserMedia({audio:{...(device==='default'?{}:{deviceId:{exact:device}}),channelCount:{ideal:1},sampleRate:{ideal:48000},echoCancellation:false,noiseSuppression:false,autoGainControl:false},video:false});if(s.closed){stream.getTracks().forEach(t=>t.stop());return;}s.stream=stream;const context=new AudioContext({sampleRate:48000});s.context=context;s.rate=context.sampleRate;const url=URL.createObjectURL(new Blob([LQTACMicrophonePCM.source()],{type:'application/javascript'}));try{await context.audioWorklet.addModule(url);}finally{URL.revokeObjectURL(url);}if(s.closed){await release();return;}s.gain=context.createGain();s.gain.gain.value=Number($('#micGain').value)/100;s.analyser=context.createAnalyser();s.analyser.fftSize=2048;s.node=new AudioWorkletNode(context,'lqtac-pcm',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1]});context.createMediaStreamSource(stream).connect(s.gain);s.gain.connect(s.analyser);s.analyser.connect(s.node);s.node.connect(context.destination);s.node.port.onmessage=event=>{if(s.closed)return;if(event.data.type==='stopped'){s.stopped?.();s.stopped=null;return;}if(event.data.type!=='samples'||!s.id)return;const bytes=event.data.data;s.frames=event.data.frames;s.backlog+=bytes.byteLength;s.queue=s.queue.then(()=>window.lqtacDesktop.microphoneRecordingAppend(s.id,bytes)).catch(error=>{s.error=error;if(s.state==='recording')void stop();}).finally(()=>{s.backlog-=bytes.byteLength;});if(s.frames/s.rate>=7200||s.backlog>2*1024*1024){if(s.state==='recording')void stop();}};stream.getAudioTracks().forEach(track=>track.onended=()=>{if(s.state==='recording'){status('Entrada desconectada. Guardando lo capturado…');void stop();}else{void release();s.state='idle';update();status('El dispositivo se ha desconectado.');}});await context.resume();s.state='ready';s.meter=requestAnimationFrame(meter);await devices();status('Entrada activa para comprobar el nivel. Pulsa Grabar para elegir dónde guardar.');update();}catch(e){await release();if(!s.closed){s.state='idle';status(microphoneError(e));update();}}}
  async function insert(saved,withLibrary=true){const position=Number($('#micPosition').value);historyCheckpoint();historyMuted++;try{if(!$$('.media-card').some(c=>c.dataset.filePath===saved.filePath)){const card=addImportedCard({name:saved.name,filePath:saved.filePath},'wav','audio');$('span',card).textContent='Micrófono · WAV 24 bits · 48 kHz · mono';$('#mediaCount').textContent=`${$$('.media-card').length} elementos`;}if($('#micAutoInsert').checked||!withLibrary){if(!Number.isFinite(position)||position<0||position+saved.durationSeconds>604800)throw Error('Posición de inserción no válida');let track=$('#micTarget').value==='new'?null:$$('.track')[Number($('#micTarget').value)];if(!track||track.dataset.kind!=='audio'){track=addTimelineTrack('audio');$$('#trackLabels .track-label strong').at(-1).textContent=track.dataset.track+' · Micrófono';}createTimelineClip(track,{kind:'audio',name:saved.name,filePath:saved.filePath,durationSeconds:saved.durationSeconds,sourceDurationSeconds:saved.durationSeconds,sourceOffsetSeconds:0},position/timelineDurationSeconds*100);s.inserted=true;}refreshTimelineScale();syncTrackHeaders();void renderTimelineAt(Number.isFinite(position)?Math.min(604800,Math.max(0,position)):timelineTime);}finally{historyMuted--;}}
  async function save(saveAs=false){s.state='saving';update();status('Guardando WAV local…');try{const result=await window.lqtacDesktop.microphoneRecordingFinish(s.id,saveAs);if(result.canceled){s.state='pending';status('Guardado cancelado: la toma temporal sigue disponible. Elige otra ruta o descarta.');return;}s.id=null;s.saved=result;s.inserted=false;s.state='done';$('#micSavedPath').textContent=result.filePath;$('#micPreview').src=await window.lqtacDesktop.mediaFileUrl(result.filePath);try{await insert(result);status('Toma guardada · '+result.durationSeconds.toFixed(2)+' s · añadida a la biblioteca'+(s.inserted?' y a la timeline':''));}catch(e){status('WAV guardado: '+e.message+'. Puedes importarlo desde su ruta.');}}catch(e){s.state='pending';status('No se ha podido guardar: '+e.message+'. La toma temporal sigue disponible; prueba otra ruta o descarta.');}finally{update();}}
  async function start(){if(s.state!=='ready')return;const position=Number($('#micPosition').value);if(!Number.isFinite(position)||position<0||position>=604800){status('Elige una posición válida para la toma.');return;}s.state='choosing';update();try{const result=await window.lqtacDesktop.microphoneRecordingStart(s.rate);if(result.canceled){await release();s.state='idle';status('Selección cancelada. Micrófono liberado.');return;}s.id=result.id;s.saved=null;s.inserted=false;s.frames=0;s.error=null;s.backlog=0;s.queue=Promise.resolve();$('#micPreview').pause();$('#micPreview').removeAttribute('src');$('#micSavedPath').textContent=result.filePath;s.state='recording';s.node.port.postMessage({type:'start'});status('Grabando PCM sin compresión con pérdida. Detener guarda el WAV y libera el micrófono.');}catch(e){await release();s.state='idle';status(e.message);}finally{update();}}
  async function stop(){if(s.state!=='recording')return;s.state='stopping';update();status('Finalizando muestras…');try{await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{s.stopped=null;reject(Error('La entrada no ha confirmado el final; puedes intentar guardar lo recibido'));},4000);s.stopped=()=>{clearTimeout(timeout);resolve();};s.node.port.postMessage({type:'stop'});});await release();await s.queue;if(s.error)throw s.error;await save();}catch(e){await release();s.state='pending';status('Toma interrumpida: '+e.message+'. Puedes intentar guardar lo recibido o descartar.');update();}}
  async function discard(){if(!['recording','pending'].includes(s.state))return;if(!confirm('¿Descartar la toma sin guardar? No se eliminan grabaciones ya guardadas.'))return;s.state='closing';update();s.node?.port.postMessage({type:'abort'});await release();await s.queue;if(s.id)await window.lqtacDesktop.microphoneRecordingAbort(s.id);s.id=null;s.state='idle';status('Toma descartada. Micrófono liberado.');update();}
  async function close(){if(['choosing','stopping','saving','closing'].includes(s.state))return;if(s.id){await discard();if(s.id)return;}s.state='closing';update();await release();$('#micPreview').pause();s.closed=true;$('.workspace').inert=s.previousInert;microphoneDialog.close();if(microphoneSession===s)microphoneSession=null;}
  $('#micRefresh').onclick=devices;$('#micPrepare').onclick=prepare;$('#micRecord').onclick=start;$('#micStop').onclick=stop;$('#micRetry').onclick=()=>save(true);$('#micDiscard').onclick=discard;$('#micClose').onclick=close;$('#micDisconnect').onclick=async()=>{await release();s.state=s.saved?'done':'idle';status('Micrófono desconectado.');update();};$('#micDevice').onchange=async()=>{if(s.stream)await release();s.state=s.saved?'done':'idle';update();status('Entrada seleccionada. Actívala para comprobar su nivel.');};$('#micGain').oninput=()=>{const gain=Number($('#micGain').value)/100;if(s.gain)s.gain.gain.setTargetAtTime(gain,s.context.currentTime,.01);$('#micGainValue').textContent=Math.round(gain*100)+' %';};$('#micInsert').onclick=async()=>{try{await insert(s.saved,false);status('Toma insertada en la pista de audio.');update();}catch(e){status(e.message);}};microphoneDialog.oncancel=event=>{event.preventDefault();void close();};
  microphoneDialog.showModal();update();await devices();
}
const micDock=document.createElement('button');micDock.type='button';micDock.className='dock-panel-item';micDock.innerHTML='<span>●</span><strong>Grabar audio</strong>';micDock.title='Grabar desde el micrófono';micDock.onclick=()=>void openMicrophoneRecorder();$('.dock-panel-list').append(micDock);
fileMenu.insertAdjacentHTML('beforeend','<button type="button" data-file="microphone">Grabar audio desde micrófono…</button>');fileMenu.addEventListener('click',event=>{if(event.target.closest('[data-file="microphone"]'))void openMicrophoneRecorder();});
